---@type GearModManifest
return {
    id = 'world-events',
    name = 'World events',
    version = '0.2.2',
    author = 'kirides',
    description = 'Shows the game server\'s world event (a realm-wide goal such as "slay 1000 orcs in 2 hours") as a small movable indicator (a pill with progress and time rings). Needs a Sacred Gear game server with the world_events script.',
    settings = {
        {id = 'visibility', type = 'choice', label = 'Show the bar', default = 'always', section = 'Progress bar',
         choices = {{value = 'always', label = 'Always while an event runs'}, {value = 'alt', label = 'Only while Alt is held'}},
         tooltip = 'Move it with the layout editor (hold Alt, then "Edit layout"). Details show on hover or while Alt is held. The controller\'s mod menu has entries that switch this and pin the details.'},
        {id = 'area', type = 'choice', label = 'Where', default = 'sector',
         choices = {{value = 'sector', label = 'Where the event counts'}, {value = 'everywhere', label = 'Everywhere'}},
         tooltip = 'Events of one sector only count there; the bar shows while you stand in that sector. Events without a sector show everywhere.'},
        {id = 'pulse', type = 'bool', label = 'Pulse at 25, 50 and 75 %', default = true,
         tooltip = 'The pill glows briefly when the realm passes a quarter of the goal'},
        {id = 'region_pill', type = 'bool', label = 'Show the region boss progress', default = true, section = 'Progress bar',
         tooltip = 'A second slim pill (teal) under the event pill while you stand in a region that counts kills towards its Region Boss: kills / needed and the percent, the game\'s own count (the Region counter mod, if you use it, sets the number the game counts to). Several pills share one movable group.'},
        {id = 'local_mode', type = 'choice', label = 'Without a server', default = 'auto', section = 'Single player',
         choices = {{value = 'auto', label = 'Run the events here (events.json)'}, {value = 'off', label = 'Do nothing'}},
         tooltip = 'In single player or a LAN game without a world_events server the mod runs the events itself from its events.json (a first run writes a small one to edit; a server export writes the same format): it counts your kills, shows the bar and fires the hooks (waves, items, gold, messages) for you.'},
        {id = 'boss_bar', type = 'bool', label = 'Show the boss health bar', default = true, section = 'World bosses',
         tooltip = 'A name and a health bar for each world boss (a boss action of an event: a creature with much more health, damage and some armour; or what the server announces). Move it with the layout editor. It takes no clicks.'},
        {id = 'results', type = 'bool', label = 'Show the result for a while', default = true,
         tooltip = 'After an event ends, one short line says whether the realm made it, then fades out (the server sets how long, 2 minutes by default)'},
    },
}
